import{_ as t,C as n,o as r,c as o,j as i,E as l,a as e,a2 as u}from"./chunks/framework.C21TwvGF.js";const p=JSON.parse('{"title":"2-hafta","description":"","frontmatter":{"title":"2-hafta","layout":"doc","sidebar":false,"aside":false,"outline":false,"kind":"hafta","hafta":{"sinf":{"name":"10-sinf (UX/UI)","link":"/10-sinf-uxui/"},"n":2,"bob":"II-bob · UX tadqiqotlari va foydalanuvchi ehtiyojlarini aniqlash","lessons":[{"g":4,"title":"4-dars: Foydalanuvchi tadqiqot usullari: intervyu, so‘rovnoma, kuzatish","lead":"Foydalanuvchi tadqiqot usullari: intervyu, so‘rovnoma, kuzatish","link":"/10-sinf-uxui/hafta-02/dars-1","slide":"/slaydlar/10-sinf-uxui/hafta-02/dars-1.html","test":"/slaydlar/10-sinf-uxui/hafta-02/dars-1-test.html"},{"g":5,"title":"5-dars: Persona va empatiya xaritasini yaratish","lead":"Persona va empatiya xaritasini yaratish","link":"/10-sinf-uxui/hafta-02/dars-2","slide":"/slaydlar/10-sinf-uxui/hafta-02/dars-2.html","test":"/slaydlar/10-sinf-uxui/hafta-02/dars-2-test.html"},{"g":6,"title":"6-dars: Foydalanuvchi tarixi va senariysini yozish (User Story & User Journey Map)","lead":"Foydalanuvchi tarixi va senariysini yozish (User Story & User Journey Map)","link":"/10-sinf-uxui/hafta-02/dars-3","slide":"/slaydlar/10-sinf-uxui/hafta-02/dars-3.html","test":"/slaydlar/10-sinf-uxui/hafta-02/dars-3-test.html"}],"test":"/slaydlar/10-sinf-uxui/hafta-02/hafta-test.html"}},"headers":[],"relativePath":"10-sinf-uxui/hafta-02/index.md","filePath":"10-sinf-uxui/hafta-02/index.md"}'),h={name:"10-sinf-uxui/hafta-02/index.md"},d={class:"blk"},y={id:"uyga-vazifa",tabindex:"-1"};function f(v,a,m,c,g,q){const s=n("Icon");return r(),o("div",null,[i("div",d,[i("h2",y,[l(s,{name:"house"}),a[0]||(a[0]=e(" Uyga vazifa ",-1)),a[1]||(a[1]=i("a",{class:"header-anchor",href:"#uyga-vazifa","aria-label":'Permalink to "<Icon name="house" /> Uyga vazifa"'},"​",-1))]),a[2]||(a[2]=u('<p>Mazkur haftada o&#39;tilgan darslar bo&#39;yicha mustaqil bajarish uchun topshiriqlar. Har bir vazifa 20–30 daqiqaga mo&#39;ljallangan.</p><hr><h3 id="_4-dars-foydalanuvchi-tadqiqot-usullari-intervyu-so-rovnoma-kuzatish" tabindex="-1">4-dars: Foydalanuvchi tadqiqot usullari: intervyu, so‘rovnoma, kuzatish <a class="header-anchor" href="#_4-dars-foydalanuvchi-tadqiqot-usullari-intervyu-so-rovnoma-kuzatish" aria-label="Permalink to &quot;4-dars: Foydalanuvchi tadqiqot usullari: intervyu, so‘rovnoma, kuzatish&quot;">​</a></h3><ol><li>O&#39;zingiz qiziqqan biror startap loyihasi (masalan, kitobxonlar uchun ijtimoiy tarmoq yoki fitnes mobil ilovasi) mavzusini tanlang.</li><li>Ushbu loyiha uchun maqsadli foydalanuvchilar bilan o&#39;tkazishga mo&#39;ljallangan 4 ta ochiq, yo&#39;naltirilmagan (xolis) sifatli intervyu savolini tuzing.</li><li>Keng auditoriya fikrini o&#39;rganish uchun 3 ta yopiq (shkala yoki variantli tanlov) so&#39;rovnoma savolini shakllantiring.</li><li>Nima uchun faqat do&#39;stlaringiz va sinfdoshlaringizdan intervyu olish yetarli emasligini 2 jumlada asoslang.</li></ol><hr><h3 id="_5-dars-persona-va-empatiya-xaritasini-yaratish" tabindex="-1">5-dars: Persona va empatiya xaritasini yaratish <a class="header-anchor" href="#_5-dars-persona-va-empatiya-xaritasini-yaratish" aria-label="Permalink to &quot;5-dars: Persona va empatiya xaritasini yaratish&quot;">​</a></h3><ol><li>Tanlagan loyihangiz bo&#39;yicha bitta asosiy maqsadli foydalanuvchi uchun to&#39;liq <strong>User Persona</strong> profilini tuzing (Ismi, yoshi, kasbi, shiori, 2 ta asosiy maqsadi, 2 ta og&#39;riqli nuqtasi).</li><li>Ushbu personaj uchun Devid Grey modeli bo&#39;yicha 4 ta asosiy kvadrantli <strong>Empatiya xaritasi</strong>ni (Says, Does, Thinks, Feels) to&#39;ldiring.</li><li>Persona va Empatiya xaritasi sizga qanday yangi g&#39;oyalar berganini 2-3 jumla bilan qayd eting.</li></ol><hr><h3 id="_6-dars-foydalanuvchi-tarixi-va-senariysini-yozish-user-story-user-journey-map" tabindex="-1">6-dars: Foydalanuvchi tarixi va senariysini yozish (User Story &amp; User Journey Map) <a class="header-anchor" href="#_6-dars-foydalanuvchi-tarixi-va-senariysini-yozish-user-story-user-journey-map" aria-label="Permalink to &quot;6-dars: Foydalanuvchi tarixi va senariysini yozish (User Story &amp; User Journey Map)&quot;">​</a></h3><ol><li>Tanlagan loyihangiz uchun Agile standarti (<code>&quot;As a..., I want..., so that...&quot;</code>) bo&#39;yicha 3 ta User Story yozing.</li><li>Ushbu 3 ta User Storydan birini tanlab, unga kamida 3 ta aniq Qabul qilish mezonini (Acceptance Criteria) ishlab chiqing.</li><li>Foydalanuvchining mahsulot bilan ilk tanishuvidan to maqsadiga erishishigacha bo&#39;lgan 4 bosqichli soddalashtirilgan User Journey Map (bosqichlar, foydalanuvchi harakatlari va his-tuyg&#39;ulari) jadvalini tuzing.</li></ol><hr>',11))])])}const b=t(h,[["render",f]]);export{p as __pageData,b as default};
